     4	const mix=(a,b,t)=>a+(b-a)*t;
     5	const smooth=x=>{x=Math.max(0,Math.min(1,x));return x*x*(3-2*x)};
     6	const distance=(a,b)=>Math.hypot(...a.map((v,i)=>v-b[i]));
