     8	export function buildGraph(route,design){
     9	  const access=[[235,168,-365],[340,168,-365],[397,168,-340],[440,168,-285],[465,168,-220],[475,168,-115],route.samples[0].slice(1)];
    10	  let offset=0;const samples=[[0,...access[0]]];
    11	  for(let i=1;i<access.length;i++){offset+=distance(access[i-1],access[i]);samples.push([offset,...access[i]])}
