    52	export class DispatchSimulation{
    53	  constructor(graph,options={}){this.graph=graph;this.config={...DEFAULTS,...options};this.nodes=new Map(graph.nodes.map(n=>[n.id,n]));this.edges=new Map(graph.edges.map(e=>[e.id,{...e}]));this.mode='auto';this.reset()}
    54	  reset(){
    55	    this.elapsed=0;this.accumulator=0;this.fuel=this.config.fuel;this.tonnes=0;this.score=0;this.status='ready';this.reason='';this.stars=0;this.paused=false;this.events=[];this.sequence=0;this.serviceQueueWait=0;this.emergencyStops=0;this.restrictions={};
    56	    this.services={CRUSHER:null,LOADER:null};this.blocks=this.graph.hubs.slice(1).map(()=>new Set());this.signals=this.graph.hubs.map(()=>({up:false,down:false}));
    57	    for(const e of this.edges.values())Object.assign(e,{owner:null,isOccupied:false,direction:null});
    58	    this.trucks=Array.from({length:4},(_,i)=>({id:'T'+(i+1),full:i>=2,state:STATES.IDLE,nodeId:i<2?this.graph.hubs[0].mainNode:this.graph.hubs.at(-1).mainNode,edgeId:null,progress:0,route:[],cursor:0,hub:i<2?0:this.graph.hubs.length-1,block:null,tail:null,temperature:28,fuelUsed:0,wait:0,serviceTime:0,command:'STOP',yielding:false,broken:false,blockedBy:null,reason:'Готов к смене',trips:0,queueOffset:(i%2)*14}));
    59	    this.log('Смена готова: две машины с грузом внизу, две пустые наверху.');
    60	  }
    61	  log(message){this.events.unshift({id:++this.sequence,time:this.elapsed,message});this.events.length=Math.min(this.events.length,60)}
    62	  start(){if(this.status==='ready'){this.status='running';this.log(this.mode==='auto'?'Автодиспетчер принял смену.':'Ручной режим: разрешите отправление машин.')}}
    63	  setMode(mode){if(!['auto','manual'].includes(mode))return;this.mode=mode;for(const t of this.trucks){t.command='STOP';t.yielding=false}this.log(mode==='auto'?'Включён автодиспетчер.':'Ручной режим: машины остановятся в ближайших безопасных узлах.')}
    64	  command(id,command){const t=this.trucks.find(t=>t.id===id);if(!t||!['STOP','GO','YIELD'].includes(command)||t.broken)return;
    65	    t.command=command;t.yielding=command==='YIELD';this.log(`${id}: ${command==='GO'?'ехать до следующего узла':command==='YIELD'?'занять карман и пропустить груз':'остановиться в ближайшем безопасном узле'}.`);
    66	  }
    67	  setSignal(hub,direction,open){if(this.signals[hub]&&['up','down'].includes(direction))this.signals[hub][direction]=!!open}
    68	  setLimit(block,kmh){if(Number.isFinite(kmh)&&kmh>=20&&kmh<=48)this.restrictions[block]=kmh}
    69	  position(t){if(!t.edgeId)return this.nodes.get(t.nodeId).position.slice();const e=this.edges.get(t.edgeId),a=this.nodes.get(e.from),b=this.nodes.get(e.to);const u=t.progress/e.length;return (t.full?b.position:a.position).map((v,i)=>mix(v,(t.full?a.position:b.position)[i],u))}
    70	  station(t){if(!t.edgeId)return this.nodes.get(t.nodeId).s;const e=this.edges.get(t.edgeId),a=this.nodes.get(e.from).s,b=this.nodes.get(e.to).s;return t.full?mix(b,a,t.progress/e.length):mix(a,b,t.progress/e.length)}
    71	  lateral(t){if(!t.edgeId)return this.nodes.get(t.nodeId).lateral;const e=this.edges.get(t.edgeId),a=this.nodes.get(e.from).lateral,b=this.nodes.get(e.to).lateral;return t.full?mix(b,a,t.progress/e.length):mix(a,b,t.progress/e.length)}
    72	  heading(t){const route=t.full?this.graph.upRoute:this.graph.downRoute;const e=this.edges.get(t.edgeId||t.route[t.cursor]||route[0]);const a=this.nodes.get(t.full?e.to:e.from).position,b=this.nodes.get(t.full?e.from:e.to).position;return b.map((v,i)=>v-a[i])}
    73	  claim(e,t){if(e.owner&&e.owner!==t.id)return false;Object.assign(e,{owner:t.id,isOccupied:true,direction:t.full?'up':'down'});return true}
    74	  release(id,t){const e=this.edges.get(id);if(e?.owner===t.id)Object.assign(e,{owner:null,isOccupied:false,direction:null})}
    75	  releaseBlock(t){if(t.block!==null)this.blocks[t.block].delete(t.id);t.block=null}
    76	  stop(t,reason,by=null){t.state=STATES.WAITING;t.reason=reason;t.blockedBy=by}
    77	  movingState(t){return t.full?STATES.MOVING_FULL:STATES.MOVING_EMPTY}
    78	  plan(t){t.route=(t.full?this.graph.upRoute:this.graph.downRoute).slice();t.cursor=0;t.queueOffset=0}
    79	  // Prediction is measured on the graph, not by Euclidean distance across benches.
    80	  meeting(t){const s=this.station(t),ve=this.config.speedKmh/3.6*this.config.distanceScale,vf=ve*this.config.fullSpeedFactor;
    81	    const full=this.trucks.filter(v=>v.full&&!v.broken&&this.station(v)>s).sort((a,b)=>this.station(a)-this.station(b))[0];
    82	    if(!full)return null;return {truck:full.id,station:s+(this.station(full)-s)*ve/(ve+vf),seconds:(this.station(full)-s)/(ve+vf)};
    83	  }
    84	  canDepart(t){
    85	    const dir=t.full?-1:1,block=t.full?t.hub-1:t.hub;
    86	    if(block<0||block>=this.blocks.length)return false;
    87	    const targetHub=t.hub+dir,otherSlot=this.trucks.find(v=>v!==t&&v.hub===targetHub&&!v.edgeId&&v.full===t.full&&!['LOADING','UNLOADING'].includes(v.state));
    88	    if(targetHub>0&&targetHub<this.graph.hubs.length-1&&otherSlot){this.stop(t,'Следующий карман занят',otherSlot.id);return false}
    89	    const direction=t.full?'up':'down';
    90	    if(this.mode==='manual'&&t.command==='STOP'&&!this.signals[t.hub][direction]){t.state=t.hub===0||t.hub===this.graph.hubs.length-1?STATES.IDLE:STATES.WAITING;t.reason='Ожидает сигнала диспетчера';return false}
    91	    if(this.mode==='auto'||t.yielding){
    92	      const convoy=[...this.blocks[block]].find(id=>id!==t.id);
    93	      if(convoy){this.stop(t,'Участок зарезервирован: '+convoy,convoy);return false}
    94	      const opposing=[...this.blocks[block]].map(id=>this.trucks.find(v=>v.id===id)).find(v=>v.full!==t.full);
    95	      if(opposing){this.stop(t,t.full?'Участок ещё освобождается':'Пропускает гружёный '+opposing.id,opposing.id);return false}
    96	      if(!t.full){
    97	        const lower=this.graph.hubs[targetHub].s;
    98	        const approaching=this.trucks.filter(v=>v.full&&this.station(v)>=this.station(t)-1).find(v=>{
    99	          const speed=this.config.speedKmh/3.6*this.config.distanceScale;
   100	          const emptySpeed=Math.min(this.config.speedKmh,this.restrictions[block]||48)/3.6*this.config.distanceScale;
   101	          const emptyETA=(lower-this.station(t))/emptySpeed;
   102	          const fullETA=Math.max(0,this.station(v)-lower)/(speed*this.config.fullSpeedFactor);
   103	          return this.station(v)<=lower||fullETA<=emptyETA+3;
   104	        });
   105	        if(approaching){this.stop(t,'Приоритет груза: '+approaching.id,approaching.id);return false}
   106	      }
   107	    }
   108	    this.blocks[block].add(t.id);t.block=block;return true;
   109	  }
   110	  beginService(t){const service=t.full?'CRUSHER':'LOADER';const owner=this.services[service];
   111	    if(owner&&owner!==t.id){this.stop(t,'Очередь: '+(t.full?'разгрузка':'загрузка'),owner);return false}
   112	    this.services[service]=t.id;t.state=t.full?STATES.UNLOADING:STATES.LOADING;t.serviceTime=t.full?this.config.unloadingSeconds:this.config.loadingSeconds;t.reason=t.full?'Разгрузка руды':'Загрузка экскаватором';t.blockedBy=null;return true;
   113	  }
   114	  advanceService(t,dt){t.serviceTime-=dt;if(t.serviceTime>0)return;
   115	    this.services[t.full?'CRUSHER':'LOADER']=null;
   116	    if(t.full){this.tonnes+=this.config.payload;this.score+=this.config.payload*10;t.trips++;this.log(`${t.id}: доставлено ${this.config.payload} т. План ${this.tonnes}/${this.config.target} т.`)}
   117	    t.full=!t.full;t.state=STATES.IDLE;t.route=[];t.command=this.mode==='auto'?'GO':'STOP';t.reason='Готов к рейсу';t.nodeId=(t.full?this.graph.hubs.at(-1):this.graph.hubs[0]).mainNode;
   118	  }
   119	  atNode(t){
   120	    const terminal=t.full?t.hub===0:t.hub===this.graph.hubs.length-1;
   121	    if(terminal){this.beginService(t);return}
   122	    if(!t.route.length)this.plan(t);
   123	    if(!this.canDepart(t))return;
   124	    const e=this.edges.get(t.route[t.cursor]);
   125	    if(!e||!this.claim(e,t)){this.releaseBlock(t);this.stop(t,'Въезд занят',e?.owner);return}
   126	    t.edgeId=e.id;t.progress=0;t.state=this.movingState(t);t.reason='';t.blockedBy=null;
   127	  }
   128	  move(t,dt){
   129	    const e=this.edges.get(t.edgeId);const kmh=Math.min(this.config.speedKmh,this.restrictions[e.block]||48);
   130	    const speed=kmh/3.6*this.config.distanceScale*(t.full?this.config.fullSpeedFactor:1);
   131	    let travel=speed*dt;
   132	    // Follow spacing is also checked across an edge boundary and at bay merges.
   133	    const ahead=this.trucks.find(v=>v!==t&&v.full===t.full&&Math.abs(this.lateral(v)-this.lateral(t))<6&&((this.station(v)-this.station(t))*(t.full?-1:1))>0&&((this.station(v)-this.station(t))*(t.full?-1:1))<this.config.truckLength+8);
   134	    if(ahead){this.stop(t,'Дистанция до '+ahead.id,ahead.id);return}
   135	    const remaining=e.length-t.progress;const endNode=this.nodes.get(t.full?e.from:e.to);
   136	    const next=this.edges.get(t.route[t.cursor+1]);
   137	    const nextOccupied=next?.owner&&next.owner!==t.id;
   138	    if(endNode.hub===null&&nextOccupied&&remaining<=travel+6){travel=Math.max(0,remaining-6);this.stop(t,'Занят следующий сегмент',next.owner)}else{t.state=this.movingState(t);t.blockedBy=null;t.reason=''}
   139	    t.progress+=Math.min(travel,remaining);
   140	    if(t.tail){t.tail.distance+=travel;if(t.tail.distance>=6){this.release(t.tail.id,t);t.tail=null}}
   141	    if(t.progress<e.length-1e-7)return;
   142	    t.nodeId=endNode.id;t.cursor++;
   143	    if(endNode.hub!==null){
   144	      this.release(e.id,t);if(t.tail){this.release(t.tail.id,t);t.tail=null}
   145	      t.edgeId=null;t.hub=endNode.hub;this.releaseBlock(t);t.state=STATES.IDLE;t.blockedBy=null;
   146	      if(this.mode==='manual')t.command=t.yielding?'YIELD':'STOP';
   147	      // Yield is a hold instruction only until the conflicting loaded convoy clears.
   148	      return;
   149	    }
   150	    if(next&&this.claim(next,t)){
   151	      if(t.tail)this.release(t.tail.id,t);
   152	      t.tail={id:e.id,distance:0};t.edgeId=next.id;t.progress=0;
   153	    }else this.stop(t,'Занят следующий сегмент',next?.owner);
   154	  }
   155	  deadlock(){
   156	    // A cycle of opposing committed trucks inside a one-lane block has no exit.
   157	    for(const t of this.trucks){if(!t.edgeId||!t.blockedBy)continue;
   158	      const chain=new Set([t.id]);let other=this.trucks.find(v=>v.id===t.blockedBy);
   159	      while(other?.edgeId&&other.blockedBy){if(chain.has(other.id)){if([...chain].some(id=>this.trucks.find(v=>v.id===id).full!==t.full)){this.emergencyStops++;this.finish(false,'Неразрешимый встречный затор между карманами');return true}break}chain.add(other.id);other=this.trucks.find(v=>v.id===other.blockedBy)}
   160	    }return false;
